import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { adminAPI } from '../services/api';
import StatCard from '../components/StatCard';
import Card from '../components/Card';
import Loader from '../components/Loader';

const WASTE_COLORS = { DRY: 'var(--eco-info)', WET: 'var(--eco-success)', E_WASTE: 'var(--eco-warning)' };
const WASTE_ICONS  = { DRY: '📦', WET: '🍃', E_WASTE: '💻' };

const AdminDashboardPage = () => {
  const [data,    setData]    = useState(null);
  const [loading, setLoading] = useState(true);
  const [error,   setError]   = useState('');

  useEffect(() => {
    adminAPI.getDashboard()
      .then(res => setData(res.data))
      .catch(() => setError('Failed to load admin dashboard data.'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <Loader fullPage text="Loading admin dashboard..." />;

  return (
    <div className="page-wrapper">
      <div className="container">

        {/* Header */}
        <div className="page-header">
          <div>
            <h1 className="page-header__title">⚙️ Admin Dashboard</h1>
            <p className="page-header__subtitle">Full platform overview — real-time data.</p>
          </div>
          <div className="page-header__actions">
            <Link to="/admin/pickups"   className="btn btn--ghost btn--sm">Pickups</Link>
            <Link to="/admin/recyclers" className="btn btn--ghost btn--sm">Recyclers</Link>
            <Link to="/admin/batches"   className="btn btn--ghost btn--sm">Batches</Link>
            <Link to="/admin/blogs"     className="btn btn--ghost btn--sm">Blogs</Link>
            <Link to="/admin/campaigns" className="btn btn--ghost btn--sm">Campaigns</Link>
            <Link to="/admin/events"    className="btn btn--primary btn--sm">Events</Link>
          </div>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {data && (
          <>
            {/* Stats Grid */}
            <div className="grid mb-8" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 'var(--space-4)' }}>
              <StatCard icon="👥" label="Total Users"     value={data.totalUsers}                        sub={`${data.totalCitizens} citizens · ${data.totalCompanies} companies`} />
              <StatCard icon="⚖️"  label="Waste Collected" value={`${data.totalWasteCollected.toFixed(1)}kg`} sub="All submissions"  accent="var(--eco-primary)" />
              <StatCard icon="💵" label="Revenue (Est.)"  value={`₹${data.totalRevenue.toFixed(2)}`}    sub="Processed batches"  accent="var(--eco-success)" />
              <StatCard icon="🚚" label="Total Pickups"   value={data.totalPickups}                      sub={`${data.pendingPickups} pending`} to="/admin/pickups" />
              <StatCard icon="♻️" label="Recyclers"       value={data.totalRecyclers}                    sub="Active partners"     to="/admin/recyclers" />
              <StatCard icon="📦" label="Waste Batches"   value={data.totalBatches}                      sub="Created batches"     to="/admin/batches" />
            </div>

            {/* Waste Breakdown + Inventory */}
            <div className="grid grid--2" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: 'var(--space-5)' }}>

              <Card>
                <Card.Header title="📊 Waste by Type" />
                <Card.Body>
                  {Object.entries(data.wasteByType).map(([type, kg]) => {
                    const total = Object.values(data.wasteByType).reduce((a, b) => a + b, 0);
                    const pct   = total > 0 ? (kg / total) * 100 : 0;
                    return (
                      <div key={type} className="mb-4">
                        <div className="flex-between mb-2" style={{ fontSize: 'var(--text-sm)' }}>
                          <span style={{ fontWeight: 500 }}>{WASTE_ICONS[type]} {type.replace('_', ' ')}</span>
                          <span style={{ color: WASTE_COLORS[type], fontWeight: 600 }}>{kg.toFixed(2)}kg ({pct.toFixed(0)}%)</span>
                        </div>
                        <div className="progress">
                          <div className="progress__bar" style={{ width: `${pct}%`, background: WASTE_COLORS[type] }} />
                        </div>
                      </div>
                    );
                  })}
                </Card.Body>
              </Card>

              <Card>
                <Card.Header title="🏭 Current Inventory" />
                <Card.Body>
                  {Object.entries(data.inventoryByType).map(([type, qty]) => (
                    <div key={type} className="flex-between" style={{ padding: 'var(--space-3) 0', borderBottom: '1px solid var(--eco-border)' }}>
                      <div className="flex gap-2" style={{ alignItems: 'center' }}>
                        <span className="dot" style={{ background: WASTE_COLORS[type] }} />
                        <span style={{ fontSize: 'var(--text-sm)', fontWeight: 500 }}>{WASTE_ICONS[type]} {type.replace('_', ' ')}</span>
                      </div>
                      <span style={{ fontWeight: 700, color: qty > 0 ? 'var(--eco-primary)' : 'var(--eco-text-muted)', fontSize: 'var(--text-base)' }}>
                        {qty.toFixed(2)}kg
                      </span>
                    </div>
                  ))}
                  <div style={{ paddingTop: 'var(--space-4)', textAlign: 'center' }}>
                    <Link to="/admin/batches" className="btn btn--primary btn--sm">Create Batch →</Link>
                  </div>
                </Card.Body>
              </Card>

            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default AdminDashboardPage;
